function isValidDate(dateStr) {
  const date = new Date(dateStr);
  return !isNaN(date.getTime()) && date.toISOString().startsWith(dateStr);
}

function isWeekday(date) {
  const day = date.getDay();
  return day >= 1 && day <= 5;
}

function isHoliday(date, holidays) {
  return holidays.includes(date.toISOString().split('T')[0]);
}

function getNextFreeDay(date, holidays) {
  let nextDay = new Date(date);
  nextDay.setDate(nextDay.getDate() + 1);
  while (isHoliday(nextDay, holidays) || !isWeekday(nextDay)) {
    nextDay.setDate(nextDay.getDate() + 1);
  }
  return nextDay;
}

export function isBusinessDay(date, holidays = []) {
  if (!isValidDate(date)) {
    throw new RangeError("Invalid date format");
  }
  const dateObj = new Date(date);
  return isWeekday(dateObj) && !isHoliday(dateObj, holidays);
}

export function addBusinessDays(date, n, holidays = []) {
  if (!isValidDate(date)) {
    throw new RangeError("Invalid date format");
  }
  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer");
  }
  const dateObj = new Date(date);
  let count = 0;
  while (count !== n) {
    dateObj.setDate(dateObj.getDate() + (n > 0 ? 1 : -1));
    if (isBusinessDay(dateObj.toISOString().split('T')[0], holidays)) {
      count += n > 0 ? 1 : -1;
    }
  }
  return dateObj.toISOString().split('T')[0].padStart(10, '0');
}

export function businessDaysBetween(start, end, holidays = []) {
  if (!isValidDate(start) || !isValidDate(end)) {
    throw new RangeError("Invalid date format");
  }
  const startDate = new Date(start);
  const endDate = new Date(end);
  if (startDate > endDate) {
    return -businessDaysBetween(end, start, holidays);
  }
  let count = 0;
  while (startDate <= endDate) {
    if (isBusinessDay(startDate.toISOString().split('T')[0], holidays)) {
      count++;
    }
    startDate.setDate(startDate.getDate() + 1);
  }
  return count;
}
